import hashlib
import hmac
import json
import string

from payhook.errors import InvalidNotification


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format."""
    timestamp = _timestamp(headers, now)
    event = _json_object(raw_body)
    payment = _payment(event)

    if not (
        _matches_v1(headers, secret, timestamp, raw_body)
        or _matches_r0(headers, secret, timestamp, event["event_id"])
    ):
        raise InvalidNotification("notification signature did not match")

    return payment


def _header(headers, name):
    if not isinstance(headers, dict):
        raise InvalidNotification("headers must be a mapping")

    lowered = name.lower()
    for key, value in headers.items():
        if isinstance(key, str) and key.lower() == lowered:
            return value
    return None


def _timestamp(headers, now):
    value = _header(headers, "X-Pay-Timestamp")
    if not isinstance(value, str) or not value or not value.isdecimal():
        raise InvalidNotification("missing or malformed timestamp")

    try:
        parsed = int(value)
    except ValueError as exc:
        raise InvalidNotification("missing or malformed timestamp") from exc

    if abs(parsed - now) > 300:
        raise InvalidNotification("stale timestamp")
    return value


def _json_object(raw_body):
    if not isinstance(raw_body, bytes):
        raise InvalidNotification("body must be bytes")

    try:
        event = json.loads(raw_body.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise InvalidNotification("malformed JSON") from exc

    if not isinstance(event, dict):
        raise InvalidNotification("JSON body must be an object")
    return event


def _payment(event):
    event_id = event.get("event_id")
    account_id = event.get("account_id")
    amount_minor = event.get("amount_minor")
    currency = event.get("currency")

    if not isinstance(event_id, str) or not event_id:
        raise InvalidNotification("missing or malformed event_id")
    if not isinstance(account_id, str) or not account_id:
        raise InvalidNotification("missing or malformed account_id")
    if (
        not isinstance(amount_minor, int)
        or isinstance(amount_minor, bool)
        or amount_minor < 0
    ):
        raise InvalidNotification("missing or malformed amount_minor")
    if (
        not isinstance(currency, str)
        or len(currency) != 3
        or any(ch not in string.ascii_uppercase for ch in currency)
    ):
        raise InvalidNotification("missing or malformed currency")

    return {
        "event_id": event_id,
        "account_id": account_id,
        "amount_minor": amount_minor,
        "currency": currency,
    }


def _matches_v1(headers, secret, timestamp, raw_body):
    digest = _digest_header(headers, "X-Pay-Signature", "v1")
    if digest is None:
        return False

    expected = hmac.new(
        secret,
        timestamp.encode("ascii") + b"." + raw_body,
        hashlib.sha256,
    ).hexdigest()
    return hmac.compare_digest(digest, expected)


def _matches_r0(headers, secret, timestamp, event_id):
    digest = _digest_header(headers, "X-Pay-Receipt", "r0")
    if digest is None:
        return False

    expected = hmac.new(
        secret,
        timestamp.encode("ascii") + b"." + event_id.encode("utf-8"),
        hashlib.sha256,
    ).hexdigest()
    return hmac.compare_digest(digest, expected)


def _digest_header(headers, header_name, version):
    value = _header(headers, header_name)
    if not isinstance(value, str):
        return None

    prefix = version + "="
    for part in value.split(","):
        candidate = part.strip()
        if candidate.startswith(prefix):
            return candidate[len(prefix):]
    return None
